  void dashboard(){clear("میز کار امروز","تقویم شمسی و اولویت‌های کاری");JalaliDate today=JalaliDate.today();LinearLayout hero=col();hero.setPadding(dp(18),dp(17),dp(18),dp(17));hero.setBackground(round(NAVY,18));TextView hi=txt(greeting()+"، کامران وحدتی",20,Color.WHITE);hi.setTypeface(null,Typeface.BOLD);hero.addView(hi);hero.addView(txt("امروز «"+today.day+" "+JalaliDate.monthName(today.month)+" "+today.year+"»",13,Color.rgb(204,214,234)));margin(hero,0,0,0,14);page.addView(hero);LinearLayout stats=row();stats.addView(stat("پرونده جاری",db.countCases("active"),"⚖",BLUE),new LinearLayout.LayoutParams(0,dp(105),1));stats.addView(stat("کار امروز",db.countToday(today.value()),"✓",GREEN),new LinearLayout.LayoutParams(0,dp(105),1));stats.addView(stat("مختومه",db.countCases("closed"),"✓",MUTED),new LinearLayout.LayoutParams(0,dp(105),1));page.addView(stats);ArrayList<OfficeDb.TaskRecord> urgent=new ArrayList<>();for(OfficeDb.TaskRecord t:db.tasksForDate(today.value()))if(t.done==0&&"فوری".equals(t.priority))urgent.add(t);section("اولویت فوری امروز",urgent.isEmpty()?"مورد فوری ثبت نشده":"تعداد: "+urgent.size());if(urgent.isEmpty())page.addView(empty("برای امروز کار فوری ندارید."));else for(OfficeDb.TaskRecord t:urgent)page.addView(taskCard(t));section("تقویم کاری شمسی","برنامه‌ها و مهلت‌های ماه");page.addView(calendar());section("برنامه "+selectedDate,"روز انتخاب‌شده");TextView add=action("+ ثبت برنامه برای این روز");add.setOnClickListener(v->addTask(selectedDate));page.addView(add);List<OfficeDb.TaskRecord> list=db.tasksForDate(selectedDate);if(list.isEmpty())page.addView(empty("برنامه‌ای برای این روز ثبت نشده است."));else for(OfficeDb.TaskRecord t:list)page.addView(taskCard(t));}
  String greeting(){int h=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);return h<12?"صبح بخیر":h<18?"روز بخیر":"شب بخیر";}
  View calendar(){LinearLayout card=col();card.setPadding(dp(12),dp(12),dp(12),dp(14));card.setBackground(round(Color.WHITE,16));LinearLayout bar=row();TextView next=action("ماه بعد ‹"),prev=action("› ماه قبل"),month=txt(JalaliDate.monthName(calMonth)+" "+calYear,16,INK);month.setGravity(Gravity.CENTER);month.setTypeface(null,Typeface.BOLD);bar.addView(next,weight());bar.addView(month,new LinearLayout.LayoutParams(0,dp(42),1.3f));bar.addView(prev,weight());card.addView(bar);prev.setOnClickListener(v->{calMonth--;if(calMonth<1){calMonth=12;calYear--;}selectedDate=ymd(calYear,calMonth,1);dashboard();});next.setOnClickListener(v->{calMonth++;if(calMonth>12){calMonth=1;calYear++;}selectedDate=ymd(calYear,calMonth,1);dashboard();});String[] wd={"ش","ی","د","س","چ","پ","ج"};LinearLayout week=row();for(String w:wd){TextView x=txt(w,12,"ج".equals(w)?RED:MUTED);x.setGravity(Gravity.CENTER);week.addView(x,new LinearLayout.LayoutParams(0,dp(34),1));}card.addView(week);int first=JalaliDate.firstWeekday(calYear,calMonth),days=JalaliDate.monthLength(calYear,calMonth),day=1;for(int r=0;r<6&&day<=days;r++){LinearLayout line=row();for(int c=0;c<7;c++){if((r==0&&c<first)||day>days)line.addView(new Space(this),new LinearLayout.LayoutParams(0,dp(48),1));else{final int d=day++;String value=ymd(calYear,calMonth,d);int count=db.countToday(value);TextView cell=txt(d+(count>0?" •":""),12,value.equals(selectedDate)?Color.WHITE:(c==6?RED:INK));cell.setGravity(Gravity.CENTER);if(value.equals(selectedDate))cell.setBackground(round(BLUE,12));cell.setOnClickListener(v->{selectedDate=value;dashboard();});line.addView(cell,new LinearLayout.LayoutParams(0,dp(48),1));}}card.addView(line);}return card;}

  void casesHub(){clear("پرونده‌ها و موکلان","مدیریت یکپارچه اشخاص و پرونده‌ها");LinearLayout tabs=row();TextView a=tab("پرونده‌ها",!clientsTab),b=tab("اشخاص و موکلان",clientsTab);a.setOnClickListener(v->{clientsTab=false;casesHub();});b.setOnClickListener(v->{clientsTab=true;casesHub();});tabs.addView(a,weight());tabs.addView(b,weight());page.addView(tabs);if(clientsTab)renderClients();else renderCases();}
  void renderCases(){LinearLayout states=row();TextView a=tab("جاری ("+db.countCases("active")+")","active".equals(caseStatus)),b=tab("مختومه ("+db.countCases("closed")+")","closed".equals(caseStatus));a.setOnClickListener(v->{caseStatus="active";casesHub();});b.setOnClickListener(v->{caseStatus="closed";casesHub();});states.addView(a,weight());states.addView(b,weight());margin(states,0,12,0,8);page.addView(states);String[] cats={"همه","کیفری","حقوقی","انقلاب","خانواده","دیوان عدالت اداری","نظامی","سایر"};Spinner filter=spinner(cats);int at=Arrays.asList(cats).indexOf(caseCategory);filter.setSelection(Math.max(0,at));filter.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){String n=cats[pos];if(!n.equals(caseCategory)){caseCategory=n;casesHub();}}});page.addView(filter);TextView add=action("+ ثبت پرونده جدید");add.setOnClickListener(v->addCase());page.addView(add);List<OfficeDb.CaseRecord> list=db.cases(caseStatus,caseCategory,null);if(list.isEmpty())page.addView(empty("در این دسته پرونده‌ای ثبت نشده است."));for(OfficeDb.CaseRecord c:list)page.addView(caseCard(c));}
  void renderClients(){TextView add=action("+ ثبت موکل جدید");add.setOnClickListener(v->addClient(null));page.addView(add);List<OfficeDb.ClientRecord> list=db.clients();if(list.isEmpty())page.addView(empty("هنوز موکلی ثبت نشده است."));for(OfficeDb.ClientRecord c:list)page.addView(clientCard(c));}
  View caseCard(OfficeDb.CaseRecord c){LinearLayout card=col();card.setPadding(dp(15),dp(14),dp(15),dp(14));card.setBackground(round(Color.WHITE,14));margin(card,0,0,0,9);LinearLayout top=row();TextView h=txt(c.title,15,INK);h.setTypeface(null,Typeface.BOLD);top.addView(h,weight());top.addView(badge(safe(c.category),BLUE));card.addView(top);card.addView(txt("موکل: "+safe(c.clientName)+" | شماره: "+safe(c.caseNumber),11,MUTED));card.addView(txt(safe(c.branch)+" | مرحله: "+safe(c.stage),11,MUTED));card.setOnClickListener(v->caseDetail(c));return card;}
