  void clientCases(OfficeDb.ClientRecord c){clear("پرونده‌های "+c.name,"تعداد کل: "+c.caseCount);detailBack=()->{clientsTab=true;casesHub();};List<OfficeDb.CaseRecord> list=db.cases(null,"همه",c.id);if(list.isEmpty())page.addView(empty("برای این موکل پرونده‌ای ثبت نشده است."));for(OfficeDb.CaseRecord x:list)page.addView(caseCard(x));}
  void caseDetail(OfficeDb.CaseRecord c){clear(c.title,("active".equals(c.status)?"پرونده جاری":"پرونده مختومه")+" · "+safe(c.category));detailBack=this::casesHub;page.addView(info("اطلاعات پرونده","شماره پرونده: "+safe(c.caseNumber)+"\nشماره بایگانی: "+safe(c.archiveNumber)+"\nمرجع: "+safe(c.reference)+"\nشعبه: "+safe(c.branch)+"\nمرحله: "+safe(c.stage)+"\nموکل: "+safe(c.clientName)));page.addView(info("موضوع و مبانی","موضوع: "+safe(c.subject)+"\nخواسته/شکایت: "+safe(c.claimText)+"\nدلایل: "+safe(c.evidence)+"\nشرح مختصر: "+safe(c.summary)));page.addView(info("وکالت و امور مالی","حق‌الوکاله: "+money(c.feeAgreed)+"\nتوافق: "+safe(c.agreementNotes)+"\nعقد وکالت: "+safe(c.contractNotes)+"\nیادداشت مالی: "+safe(c.financialNotes)));LinearLayout buttons=row();TextView status=action("active".equals(c.status)?"انتقال به مختومه":"بازگشت به جاری"),finance=action("حسابداری پرونده");status.setOnClickListener(v->{db.updateCaseStatus(c.id,"active".equals(c.status)?"closed":"active");caseStatus="active".equals(c.status)?"closed":"active";casesHub();});finance.setOnClickListener(v->finance(c));buttons.addView(status,weight());buttons.addView(finance,weight());page.addView(buttons);}
  void finance(OfficeDb.CaseRecord c){clear("حسابداری پرونده",c.title);detailBack=()->caseDetail(c);OfficeDb.AccountSummary a=db.summary(c);LinearLayout stats=row();stats.addView(stat("دریافت",a.received,"ریال",GREEN),new LinearLayout.LayoutParams(0,dp(108),1));stats.addView(stat("بدهی موکل",a.debt,"ریال",RED),new LinearLayout.LayoutParams(0,dp(108),1));page.addView(stats);page.addView(info("جمع‌بندی مالی","حق‌الوکاله: "+money(a.agreed)+"\nکل هزینه‌ها: "+money(a.expenses)+"\nپرداخت وکیل: "+money(a.lawyerPaid)+"\nبازپرداخت موکل: "+money(a.reimbursed)+"\nبستانکاری موکل: "+money(a.credit)));TextView add=action("+ ثبت دریافت یا هزینه");add.setOnClickListener(v->addLedger(c));page.addView(add);for(OfficeDb.LedgerRecord l:db.ledger(c.id))page.addView(info(l.category+" · "+money(l.amount),safe(l.date)+" | پرداخت‌کننده: "+safe(l.paidBy)+"\n"+safe(l.description)));}

  void tasks(){clear("برنامه کاری","جلسات، مهلت‌ها و کارهای آتی");TextView add=action("+ افزودن کار، جلسه یا مهلت");add.setOnClickListener(v->addTask(null));page.addView(add);List<OfficeDb.TaskRecord> list=db.openTasks(200);if(list.isEmpty())page.addView(empty("کار بازی ثبت نشده است."));for(OfficeDb.TaskRecord t:list)page.addView(taskCard(t));}
