  void addLedger(OfficeDb.CaseRecord c){LinearLayout f=form();Spinner kind=spinner(new String[]{"دریافت حق‌الوکاله","بازپرداخت هزینه توسط موکل","هزینه پرونده"}),category=spinner(new String[]{"حق‌الوکاله","بازپرداخت هزینه","هزینه دادرسی","کارشناسی","تمبر و خدمات قضایی","هتل","بلیط هواپیما","تاکسی و فرودگاه","اقامت و مأموریت","سایر"}),paid=spinner(new String[]{"موکل","وکیل","شخص ثالث"});EditText amount=input("مبلغ به ریال"),date=input("تاریخ شمسی"),desc=area("شرح هزینه یا پرداخت");amount.setInputType(InputType.TYPE_CLASS_NUMBER);date.setText(JalaliDate.today().value());for(View v:new View[]{kind,category,amount,date,paid,desc})f.addView(v);new AlertDialog.Builder(this).setTitle("ثبت عملیات مالی").setView(scroll(f)).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(d,w)->{String k=kind.getSelectedItemPosition()==2?"expense":"payment",cat=kind.getSelectedItemPosition()==0?"حق‌الوکاله":kind.getSelectedItemPosition()==1?"بازپرداخت هزینه":category.getSelectedItem().toString();db.addLedger(c.id,k,cat,parseMoney(amount.getText().toString()),date.getText().toString(),paid.getSelectedItem().toString(),desc.getText().toString());finance(c);}).show();}

  void reports(){clear("گزارش‌گیری","خروجی فهرست‌ها، پرونده‌ها و امور مالی");String[][] a={{"گزارش موکلان","نام، تلفن، نشانی و تعداد پرونده"},{"پرونده‌های جاری","همه پرونده‌های در حال پیگیری"},{"پرونده‌های مختومه","فهرست سوابق مختومه"},{"گزارش کیفری","پرونده‌های کیفری"},{"گزارش حقوقی","پرونده‌های حقوقی"},{"گزارش خانواده","پرونده‌های خانواده"},{"گزارش جامع مالی","حق‌الوکاله، هزینه، بدهی و طلب"}};for(int i=0;i<a.length;i++){final int n=i;View v=info(a[i][0],a[i][1]+"\nبرای پیش‌نمایش و PDF لمس کنید.");v.setOnClickListener(x->runReport(n));page.addView(v);}}
  void runReport(int type){String heading,body;if(type==0){heading="گزارش موکلان";StringBuilder b=new StringBuilder();for(OfficeDb.ClientRecord c:db.clients())b.append(c.name).append("\nتلفن: ").append(safe(c.phone)).append(" | کد ملی: ").append(safe(c.nationalId)).append("\nنشانی: ").append(safe(c.address)).append("\nپرونده‌ها: ").append(c.caseCount).append(" (جاری: ").append(c.activeCount).append(")\n\n");body=b.toString();}else if(type==6){heading="گزارش جامع مالی";StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:db.cases(null,"همه",null)){OfficeDb.AccountSummary a=db.summary(c);b.append(c.title).append(" | موکل: ").append(safe(c.clientName)).append("\nحق‌الوکاله: ").append(money(a.agreed)).append(" | دریافتی: ").append(money(a.received)).append("\nهزینه: ").append(money(a.expenses)).append(" | بدهی: ").append(money(a.debt)).append(" | بستانکاری: ").append(money(a.credit)).append("\nتوافق: ").append(safe(c.agreementNotes)).append("\n\n");}body=b.toString();}else{String status=type==1?"active":type==2?"closed":null,cat=type==3?"کیفری":type==4?"حقوقی":type==5?"خانواده":"همه";heading=type==1?"پرونده‌های جاری":type==2?"پرونده‌های مختومه":"پرونده‌های "+cat;StringBuilder b=new StringBuilder();for(OfficeDb.CaseRecord c:db.cases(status,cat,null))b.append(c.title).append("\nشماره: ").append(safe(c.caseNumber)).append(" | بایگانی: ").append(safe(c.archiveNumber)).append("\nموکل: ").append(safe(c.clientName)).append(" | دسته: ").append(safe(c.category)).append("\nموضوع: ").append(safe(c.subject)).append(" | شعبه: ").append(safe(c.branch)).append("\n\n");body=b.toString();}preview(heading,body);}
  void preview(String h,String body){ScrollView s=new ScrollView(this);TextView v=txt(body,13,INK);v.setPadding(dp(18),dp(14),dp(18),dp(14));v.setTextIsSelectable(true);s.addView(v);new AlertDialog.Builder(this).setTitle(h).setView(s).setNegativeButton("بستن",null).setPositiveButton("PDF / چاپ",(d,w)->print(h,html(h,body))).show();}

  void letter(){clear("لایحه و سربرگ","تنظیم متن و دریافت PDF رسمی");List<OfficeDb.CaseRecord> cases=db.cases(null,"همه",null);ArrayList<String> names=new ArrayList<>();names.add("بدون اتصال به پرونده");for(OfficeDb.CaseRecord c:cases)names.add(c.title);Spinner pick=spinner(names.toArray(new String[0]));EditText subject=input("عنوان لایحه یا نامه"),body=area("متن کامل لایحه را اینجا وارد کنید...");body.setMinLines(12);TextView p=action("ساخت سربرگ و خروجی PDF");p.setOnClickListener(v->{OfficeDb.CaseRecord c=pick.getSelectedItemPosition()>0?cases.get(pick.getSelectedItemPosition()-1):null;String meta=c==null?"":"شماره پرونده: "+safe(c.caseNumber)+" | بایگانی: "+safe(c.archiveNumber)+" | شعبه: "+safe(c.branch)+"\n";print(subject.getText().toString(),html(subject.getText().toString(),meta+body.getText().toString()));});page.addView(pick);page.addView(subject);page.addView(body);page.addView(p);page.addView(info("راهنما","مشخصات وکیل و لوگو از بخش اطلاعات وکیل روی سربرگ درج می‌شود. در صفحه چاپ، Save as PDF را انتخاب کنید."));}
  void lawyer(){clear("اطلاعات وکیل","مشخصات سربرگ و گزارش‌ها");LinearLayout images=row();ImageView photo=image(prefs.getString("photo",null)),logo=image(prefs.getString("logo",null));images.addView(photo,new LinearLayout.LayoutParams(0,dp(125),1));images.addView(logo,new LinearLayout.LayoutParams(0,dp(125),1));page.addView(images);LinearLayout choose=row();TextView p=action("انتخاب عکس وکیل"),l=action("انتخاب لوگوی کانون/مرکز");p.setOnClickListener(v->pickImage(PHOTO));l.setOnClickListener(v->pickImage(LOGO));choose.addView(p,weight());choose.addView(l,weight());page.addView(choose);EditText name=input("نام و نام خانوادگی"),license=input("شماره پروانه وکالت"),center=input("کانون یا مرکز وکلا"),phone=input("شماره تلفن"),address=area("نشانی دفتر"),website=input("وب‌سایت");name.setText(prefs.getString("name","کامران وحدتی"));license.setText(prefs.getString("license",""));center.setText(prefs.getString("center","کانون وکلای دادگستری مرکز"));phone.setText(prefs.getString("phone",""));address.setText(prefs.getString("address",""));website.setText(prefs.getString("website","kamranvahdati.ir"));for(View v:new View[]{name,license,center,phone,address,website})page.addView(v);TextView save=action("ذخیره اطلاعات وکیل");save.setOnClickListener(v->{prefs.edit().putString("name",name.getText().toString()).putString("license",license.getText().toString()).putString("center",center.getText().toString()).putString("phone",phone.getText().toString()).putString("address",address.getText().toString()).putString("website",website.getText().toString()).apply();toast("اطلاعات وکیل ذخیره شد");});page.addView(save);}
  void pickImage(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,code);}

  void backup(){clear("پشتیبان‌گیری امن","انتقال کنترل‌شده اطلاعات بین گوشی‌ها");page.addView(info("روش امن آفلاین","یک فایل رمزگذاری‌شده با پسوند .klo ساخته می‌شود. شما مقصد یا دریافت‌کننده را انتخاب می‌کنید و گوشی مقصد فقط با همان کد قادر به بازیابی است. کد را جداگانه منتقل کنید."));EditText code=input("کد پشتیبان حداقل ۶ رقم یا حرف");code.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);TextView export=action("ساخت فایل پشتیبان رمزگذاری‌شده"),restore=action("بازیابی فایل پشتیبان در این گوشی");export.setOnClickListener(v->{if(code.length()<6){toast("کد حداقل ۶ کاراکتر باشد");return;}pendingCode=code.getText().toString();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"دفتر-وکالت-"+JalaliDate.today().value().replace('/','-')+".klo");startActivityForResult(i,EXPORT);});restore.setOnClickListener(v->{if(code.length()<6){toast("ابتدا کد فایل را وارد کنید");return;}pendingCode=code.getText().toString();new AlertDialog.Builder(this).setTitle("تأیید بازیابی").setMessage("اطلاعات فعلی با محتوای فایل جایگزین می‌شود. ادامه می‌دهید؟").setNegativeButton("خیر",null).setPositiveButton("ادامه",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}).show();});page.addView(code);page.addView(export);page.addView(restore);}
  @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(req==PHOTO||req==LOGO){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);prefs.edit().putString(req==PHOTO?"photo":"logo",uri.toString()).apply();lawyer();}else if(req==EXPORT){byte[] bytes=SecureBackup.encrypt(db.exportJson(),pendingCode);try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(bytes);}toast("پشتیبان رمزگذاری‌شده ذخیره شد");}else if(req==IMPORT){db.importJson(SecureBackup.decrypt(readAll(uri),pendingCode));toast("اطلاعات بازیابی شد");go(HOME,false);}}catch(Exception e){new AlertDialog.Builder(this).setTitle("عملیات انجام نشد").setMessage("کد نادرست است یا فایل معتبر نیست.\n\n"+e.getClass().getSimpleName()).setPositiveButton("باشه",null).show();}finally{pendingCode=null;}}
  byte[] readAll(Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
