  String html(String heading,String body){String logo=imageData(prefs.getString("logo",null)),img=blank(logo)?"":"<img src='"+logo+"' style='width:72px;height:72px;object-fit:contain'>",name=esc(prefs.getString("name","کامران وحدتی")),license=esc(prefs.getString("license","")),center=esc(prefs.getString("center","")),phone=esc(prefs.getString("phone","")),address=esc(prefs.getString("address","")),web=esc(prefs.getString("website",""));return "<!doctype html><html dir='rtl'><head><meta charset='utf-8'><style>@page{size:A4;margin:18mm}body{font-family:sans-serif;direction:rtl;color:#182236;line-height:2}.head{display:flex;align-items:center;border-bottom:3px solid #152446;padding-bottom:12px}.brand{flex:1}h1,h2,p{margin:0}.meta{font-size:12px;color:#566176}.body{white-space:pre-wrap;margin-top:28px;font-size:14px}.foot{margin-top:50px;border-top:1px solid #bbb;padding-top:8px;font-size:11px}</style></head><body><div class='head'>"+img+"<div class='brand'><h1>دفتر وکالت "+name+"</h1><p>وکیل پایه یک دادگستری · "+center+"</p><p class='meta'>شماره پروانه: "+license+"</p></div></div><h2 style='text-align:center;margin-top:24px'>"+esc(heading)+"</h2><div class='body'>"+esc(body)+"</div><div class='foot'>تلفن: "+phone+" | نشانی: "+address+" | "+web+"</div></body></html>";}
  void print(String name,String html){printView=new WebView(this);printView.getSettings().setDefaultTextEncodingName("UTF-8");printView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print(name,v.createPrintDocumentAdapter(name),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).build());}});printView.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);}
  String imageData(String value){if(blank(value))return "";try(InputStream in=getContentResolver().openInputStream(Uri.parse(value));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return "data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);}catch(Exception e){return "";}}

