  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;} TextView txt(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
  GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;} LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);} LinearLayout.LayoutParams weight(){return new LinearLayout.LayoutParams(0,-2,1);} void margin(View v,int l,int t,int r,int b){LinearLayout.LayoutParams p=v.getLayoutParams() instanceof LinearLayout.LayoutParams?(LinearLayout.LayoutParams)v.getLayoutParams():new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(l),dp(t),dp(r),dp(b));v.setLayoutParams(p);} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
  boolean blank(String s){return s==null||s.trim().isEmpty();} String safe(String s){return blank(s)?"ثبت نشده":s;} long parseMoney(String s){try{return Long.parseLong(s.replace(",","").replace("٬","").trim());}catch(Exception e){return 0;}} String money(long v){return String.format(Locale.US,"%,d ریال",v);} String ymd(int y,int m,int d){return String.format(Locale.US,"%04d/%02d/%02d",y,m,d);} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} String esc(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>");}
